import express from "express"

const app = express()
const issues = [
  { id: 1, title: "Login button does nothing on mobile", status: "open" },
  { id: 2, title: "Export report as CSV", status: "done" },
]

app.get("/api/issues", (req, res) => {
  res.json(issues)
})

app.get("/api/issues/:id", (req, res) => {
  const issue = issues.find((i) => i.id === Number(req.params.id))
  if (!issue) return res.status(404).json({ error: "no such issue" })
  res.json(issue)
})

app.listen(3000, () => console.log("Listening on port 3000"))

