import { useState } from "react"

export default function AddIssueForm({ onAdd }) {
  const [title, setTitle] = useState("")
  const [error, setError] = useState("")
  function submit(e) {
    e.preventDefault()
    if (!title.trim()) return setError("A title is required.")
    onAdd(title.trim())
    setTitle("")
    setError("")
  }
  return (
    <form onSubmit={submit}>
      <input value={title} onChange={(e) => setTitle(e.target.value)} aria-label="Issue title" />
      <button type="submit">Add</button>
      {error && <p role="alert">{error}</p>}
    </form>
  )
}

export default function Column({ title, issues, onMove, onRemove }) {
  return (
    <section>
      <h2>{title} <span>{issues.length}</span></h2>
      {issues.map((issue) => (
        <IssueCard key={issue.id} issue={issue} onMove={onMove} onRemove={onRemove} />
      ))}
    </section>
  )
}

