const BUG = ["crash", "error", "broken", "does nothing", "wrong"]
const URGENT = ["production", "blocked", "urgent", "all users"]

export function labelByRules(title) {
  const t = title.toLowerCase()
  const label = BUG.some((w) => t.includes(w)) ? "bug" : "feature"
  const priority = URGENT.some((w) => t.includes(w)) ? "high" : "normal"
  return { label, priority, source: "rules" }
}

