import Anthropic from "@anthropic-ai/sdk"
const client = new Anthropic()   // ANTHROPIC_API_KEY from the environment

export async function suggest(title) {
  const reply = await client.messages.create({
    model: "claude-sonnet-5-5",
    max_tokens: 100,
    system: "You label software issues for a small team. Reply with a label (bug or feature) and a priority (high or normal) and nothing else.",
    messages: [{ role: "user", content: `Issue title: ${title}` }],
  })
  return reply.content[0].text
}

const LABELS = ["bug", "feature"]
const PRIORITIES = ["high", "normal"]

export function validSuggestion(s) {
  return (
    s && LABELS.includes(s.label) && PRIORITIES.includes(s.priority) &&
    ["high", "low"].includes(s.confidence)
  )
}

